<?php
require 'config.php'; require_admin();
function is_public_host(string $host): bool { if (filter_var($host,FILTER_VALIDATE_IP)) return (bool)filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE); if ($host==='localhost' || str_ends_with($host,'.localhost') || str_ends_with($host,'.local')) return false; $records=@dns_get_record($host,DNS_A|DNS_AAAA); if (!$records) return false; foreach($records as $r){$ip=$r['ip']??$r['ipv6']??''; if($ip!=='' && !filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)) return false;} return true; }
$start=trim((string)($_POST['start_url']??'')); $domainsRaw=trim((string)($_POST['allowed_domains']??'')); $maxPages=max(1,min(100,(int)($_POST['max_pages']??30))); $maxDepth=max(0,min(8,(int)($_POST['max_depth']??3))); $timeout=max(2,min(10,(int)($_POST['timeout']??3))); $duration=max(5,min(60,(int)($_POST['duration']??30))); $error=''; $host=''; $domains=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$p=parse_url($start);if(!filter_var($start,FILTER_VALIDATE_URL)||!$p||!in_array(strtolower($p['scheme']??''),['http','https'],true)||empty($p['host'])||isset($p['user']))$error='URL bắt đầu không hợp lệ.';else{$host=strtolower($p['host']);$domains=$domainsRaw===''?[$host]:array_values(array_unique(array_map(fn($x)=>strtolower(trim($x)),explode(',',$domainsRaw))));if(!in_array($host,$domains,true))$error='Domain của URL bắt đầu phải nằm trong danh sách cho phép.';foreach($domains as $d)if(!preg_match('/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\.(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?))*$/i',$d))$error='Danh sách domain có hostname không hợp lệ.';if(!$error&&!is_public_host($host))$error='Không thể xác minh domain công khai. Địa chỉ localhost/mạng nội bộ bị chặn theo mặc định.';}}
layout_start('Xem trước phạm vi'); ?>
