<?php if($_SERVER['REQUEST_METHOD']==='POST'):?><div class="card p-4 mt-4"><?php if($error!==''):?><div class="alert alert-danger mb-0"><?=e($error)?></div><?php else:?><h2 class="h5 fw-bold">Cấu hình hợp lệ sơ bộ</h2><p class="mb-2"><strong>URL gốc:</strong> <span class="wrap-url"><?=e($start)?></span></p><p class="mb-2"><strong>Domain được phép:</strong> <?=e(implode(', ',$domains))?></p><p class="mb-2"><strong>Giới hạn:</strong> <?=$maxPages?> trang · độ sâu <?=$maxDepth?> · timeout <?=$timeout?> giây · tối đa <?=$duration?> giây.</p><div class="alert alert-warning">Đây là xem trước cấu hình, chưa xác nhận URL nào tồn tại. Khi quét, mọi URL và đích chuyển hướng sẽ được kiểm tra lại theo allowlist.</div><form method="post" action="scan.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="name" value="<?=e($_POST['name']??'Kiểm tra website')?>"><input type="hidden" name="start_url" value="<?=e($start)?>"><input type="hidden" name="allowed_domains" value="<?=e(implode(',',$domains))?>"><input type="hidden" name="max_pages" value="<?=$maxPages?>"><input type="hidden" name="max_depth" value="<?=$maxDepth?>"><input type="hidden" name="timeout" value="<?=$timeout?>"><input type="hidden" name="duration" value="<?=$duration?>"><button class="btn btn-primary">Bắt đầu quét với cấu hình này</button></form><?php endif;?></div><?php endif;?><?php layout_end(); ?>